\begin{aligned}
\operatorname{Closed}_{\Lambda,\Gamma}(X)
\Longleftrightarrow{}&
\Gamma\subseteq X
\ \wedge\ 
\mathsf{Ax}_{CLIF}\subseteq X\\
&\wedge\
\forall L\in\Lambda\ \forall A\in\mathsf{Frm}_{CLIF}
((L,A)\in\operatorname{ParseF}\Rightarrow A\in X)\\
&\wedge\
\forall A,B\in\mathsf{Frm}_{CLIF}
(A\in X\wedge\operatorname{if}(A,B)\in X\Rightarrow B\in X)\\
&\wedge\
\forall A\in\mathsf{Frm}_{CLIF}\ \forall x\in\mathsf{Var}
(A\in X\wedge x\notin\bigcup_{G\in\Gamma}\operatorname{FV}_F(G)
\Rightarrow \operatorname{forall}(x,A)\in X)\\
&\wedge\
\forall A,B\in\mathsf{Frm}_{CLIF}
(A\in X\wedge A\equiv_\alpha B\Rightarrow B\in X).
\end{aligned}
